#!/bin/bash
# XAI tail of the pipeline: explanations -> case study -> report  (planner 6, 7.2).
#   bash run_xai.sh [workers]
# Do not edit this file while it runs: bash reads it incrementally.
set -u
cd "$(dirname "$0")"
export PYTHONPATH=.
W=${1:-4}
LOG=runs/pipeline.log
say() { echo "[$(date +%H:%M:%S)] $*" | tee -a $LOG; }
say "explain (re-run after the log-sigmoid fix of CornHead.class_logits)"
python -m src.xai.explain_sweep --workers "$W" >> $LOG 2>&1
say "case study";  python -m src.eval.case_study >> $LOG 2>&1
say "report";      python -m src.eval.report >> $LOG 2>&1
say "pipeline done"
